import {escapeText as esc,icon} from './assets.js';
import {categories,isPublished} from './menu-query.js';
import {menuStatistics} from './catalog-stats.js';
export function menuMarkup({items,dishes,filters,allMeals,mainOnly=false,limit,card,empty}){
 const stats=menuStatistics(dishes),names=new Set(items.map(d=>d.dishGroupId??d.canonicalName));
 return `<div class="menu-role-switch"><button class="button ${mainOnly?'primary':'secondary'}" data-action="menu-main" aria-pressed="${mainOnly}">${icon('bowl')}主餐优先</button><span>${mainOnly?'只看可安排为一餐的灵感':'全部灵感，也可以只看主餐'}</span></div><div class="category-chips" role="group" aria-label="餐品分类"><button data-action="all-categories" aria-pressed="${!filters.categories.length}">全部分类</button>${categories.filter(c=>dishes.some(d=>isPublished(d)&&d.category===c)).map(c=>`<button data-action="category" data-value="${esc(c)}" aria-pressed="${filters.categories.includes(c)}">${esc(c)}</button>`).join('')}</div><div class="section-head menu-head"><div><h2>${filters.query?'找到你想吃的味道':'今天的好胃口，从这里开始'}</h2><p>主餐、小食、甜点，按喜欢的慢慢挑。</p></div><span>${items.length}份灵感 <span class="muted">/ ${names.size}种菜名</span></span></div>${items.length?`<div class="menu-grid">${items.slice(0,limit).map(d=>card(d)).join('')}</div>${items.length>limit?`<button class="button secondary load-more" data-action="load-more">再看看24份灵感 ${icon('arrow')}</button>`:'<p class="end-note">已经逛完这一组，换个分类再看看。</p>'}`:empty('这个条件下，还没找到合适的','可以减少筛选，或恢复今天跳过的餐品。','<button class="button secondary" data-action="clear-filters">清除筛选</button>')}<div class="menu-note"><p>${stats.publishedRecordCount}条独立记录，${stats.publishedGroupCount}种不同菜名。主餐可用于抽餐和周计划；配菜、甜品可浏览收藏。</p><p>餐品示意，供应未核对。口味与餐次为选餐参考，不代表某个窗口的实际菜单。</p></div>`;
}
